function loadPdf(url,container){function getPdfPageContainer(pageNumber){let sigSelector;try{sigSelector=signatureSelector}catch(e){sigSelector=undefined}let canvas=document.createElement("canvas");return canvas.classList.add("embeded-pdf-page"),canvas.setAttribute("data-page",pageNumber),sigSelector!==undefined&&(canvas.addEventListener("mousedown",sigSelector.mouseDownHandler),canvas.addEventListener("mousemove",sigSelector.mouseMoveHandler),canvas.addEventListener("mouseup",sigSelector.mouseUpHandler)),canvas}var{pdfjsLib}=globalThis,loadingTask;pdfjsLib.GlobalWorkerOptions.workerSrc="/js/pdfjs/pdf.worker.mjs";loadingTask=pdfjsLib.getDocument(url);loadingTask.promise.then(function(pdf){let numPages=pdf.numPages;for(let pageNumber=1;pageNumber<=numPages;pageNumber++)pdf.getPage(pageNumber).then(function(page){let viewport=page.getViewport({scale:1}),canvas=getPdfPageContainer(page.pageNumber);container.appendChild(canvas);let context=canvas.getContext("2d");canvas.height=viewport.height;canvas.width=viewport.width;let renderContext={canvasContext:context,viewport:viewport},renderTask=page.render(renderContext);renderTask.promise.then(function(){})})},function(reason){console.error(reason)})}$(function(){$("#verifySignatureButton").on("click",function(e){let url=$(e.target).data("url");fetch(url).then(r=>r.json()).then(signatureData=>{signatureData.isValid?Swal.fire({title:"Валиден подпис!",text:`Този файл е подписан от ${signatureData.name} на ${signatureData.date} в ${signatureData.time}`,icon:"success"}):Swal.fire({title:"Невалиден подпис!",text:"Подписът не може да бъде валидиран",icon:"error"})})})});